def analyze(g):
    H,W=len(g),len(g[0])
    five={(y,x) for y in range(H) for x in range(W) if g[y][x]==5}
    # tree paths: BFS between endpoints
    ends=[c for c in five if len([n for n in nb4g(g,*c) if n in five])==1]
    def path(a,b):
        from collections import deque
        q=deque([a]);prev={a:None}
        while q:
            c=q.popleft()
            if c==b:break
            for n in nb4g(g,*c):
                if n in five and n not in prev: prev[n]=c;q.append(n)
        p=[];c=b
        while c:p.append(c);c=prev[c]
        return p[::-1]
    best=None
    for a,b in itertools.combinations(ends,2):
        L=len(path(a,b))
        if best is None or L>best[0]: best=(L,a,b)
    L,ma,mb=best
    main=set(path(ma,mb))
    teeth=[e for e in ends if e not in (ma,mb)]
    # order teeth by distance along main path to attachment
    # prong of tooth = path from tip to main path
    def prong(tip):
        # BFS from tip until hitting main
        from collections import deque
        q=deque([tip]);prev={tip:None}
        while q:
            c=q.popleft()
            if c in main and c!=tip: break
            for n in nb4g(g,*c):
                if n in five and n not in prev: prev[n]=c;q.append(n)
        p=[];c=q[0]
        while c is not None:p.append(c);c=prev[c]
        return p  # tip..attachment(on main)
    prongs={t:prong(t) for t in teeth}
    att={t:p[-1] for t,p in prongs.items()}
    # order teeth along main path by index of attachment in path(ma,mb)
    mp=path(ma,mb); idx={c:i for i,c in enumerate(mp)}
    teeth_sorted=sorted(teeth,key=lambda t:idx[att[t]])
    # zero pockets
    zero={(y,x) for y in range(H) for x in range(W) if g[y][x]==0}
    pockets=[];seenp=set()
    for c in zero:
        if c in seenp:continue
        st=[c];seenp.add(c);comp=[]
        while st:
            a=st.pop();comp.append(a)
            for n in nb4g(g,*a):
                if n in zero and n not in seenp: seenp.add(n);st.append(n)
        pockets.append(comp)
    # for each pocket, which prongs/border touch
    info=[]
    for comp in pockets:
        wall=set()
        for (y,x) in comp:
            for n in nb4g(g,y,x):
                if n in five: wall.add(n)
        touchprongs=[t for t,p in prongs.items() if wall & set(p)]
        touchmain = any(wall & main)
        info.append((comp,sorted(touchprongs),touchmain))
    return dict(main_ends=(ma,mb),main_path=mp,teeth=teeth_sorted,prongs=prongs,pockets=info,ends=ends)

